package web3

import (
	"encoding/hex"
	"math/big"
	"strings"
	"testing"

	"github.com/ethereum/go-ethereum/common"
	"github.com/polymas/go-polymarket-sdk/signing"
)

// TestBuildCWIABatchCalldataMatchesOnChainTx 用真实链上 tx 的 calldata 作为
// 黄金对照，验证 BuildCWIABatchCalldata 与 Polymarket 后端编码完全一致。
//
// 样例：tx 0xf9661f53bfa269f2c26a90622dfbce7cbacee245342caae1d13fc4cab16ad825
// （详细参数见 signing/cwia_batch_test.go 的 TestCWIABatchHashAgainstOnChainSample）
func TestBuildCWIABatchCalldataMatchesOnChainTx(t *testing.T) {
	const expectedHex = ""

	callData, _ := hex.DecodeString("a9059cbb00000000000000000000000088422c0f9a1e01db293a92f3d5684d6e29a0ba93000000000000000000000000000000000000000000000000000000000001de1b")
	batch := signing.CWIABatch{
		Wallet:   common.HexToAddress("0xa497f6d9b942f3a73e24f9642316f0979c677891"),
		Nonce:    big.NewInt(877),
		Deadline: big.NewInt(1777987422),
		Calls: []signing.CWIACall{{
			Target: common.HexToAddress("0xc011a7e12a19f7b1f670d46f03b03f3342e82dfb"),
			Value:  big.NewInt(0),
			Data:   callData,
		}},
	}
	sig, _ := hex.DecodeString("b17775663e1ff56d99d60214987793d8626b44edeacef39411c47b4e6a7dcc487062a324214a1828a73d03b26a22a27aebdc4a4f7926b746a2dd34ed10b554341c")

	got, err := BuildCWIABatchCalldata(batch, sig)
	if err != nil {
		t.Fatal(err)
	}
	gotHex := "0x" + hex.EncodeToString(got)
	if !strings.EqualFold(gotHex, expectedHex) {
		t.Fatalf("calldata mismatch:\n  expected = %s\n  got      = %s", expectedHex, gotHex)
	}
}
